window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _k2 = SLP.books.find(function(b){ return b.id === "2-kgs"; });
if (!_k2) throw new Error("data/canon.js must load before ot-12-2kings.js");
(_k2.chapters = _k2.chapters || []).push(
  { n:1, summary:"After Ahab's death, Moab rebels against Israel. Ahaziah, Ahab's son and king in Samaria, falls through a lattice in his upper chamber, and when he is sick he sends messengers to inquire of Baal-zebub, the god of Ekron, about his recovery. Elijah meets the messengers with the Lord's question: because there is a God in Israel, why seek an idol? The king will surely die in his bed. Learning that a hairy man in a leather girdle has spoken, Ahaziah sends three captains with their fifties to arrest Elijah. Fire from heaven consumes the first two companies, but the third captain kneels and pleads for his life, and the angel sends Elijah down to deliver the sentence in person. Ahaziah dies according to the word of the Lord, and Jehoram reigns in his place.",
    context:"After Ahab's death, his injured son Ahaziah rules the northern kingdom of Israel; the book itself is anonymous.",
    keyVerses:[
      { ref:"2 Kings 1:3", text:"But the angel of the LORD said to Elijah the Tishbite, Arise, go up to meet the messengers of the king of Samaria, and say unto them, Is it not because there is not a God in Israel, that ye go to inquire of Baal-zebub the god of Ekron?" },
      { ref:"2 Kings 1:13", text:"And he sent again a captain of the third fifty with his fifty. And the third captain of fifty went up, and came and fell on his knees before Elijah, and besought him, and said unto him, O man of God, I pray thee, let my life, and the life of these fifty thy servants, be precious in thy sight." },
      { ref:"2 Kings 1:17", text:"So he died according to the word of the LORD which Elijah had spoken. And Jehoram reigned in his stead in the second year of Jehoram the son of Jehoshaphat king of Judah; because he had no son." }
    ],
    takeaway:"Seek the living God in trouble; consulting substitutes for Him invites the very answers we fear.",
    quiz:[
      { q:"Which god did Ahaziah send messengers to consult about his recovery?", choices:["Baal-zebub, the god of Ekron","Chemosh of Moab","Baal of Mount Carmel","Molech of Ammon"], a:0, why:"Sick from his fall through a lattice, Ahaziah sent messengers to inquire of Baal-zebub the god of Ekron whether he would recover." },
      { q:"Why was the third captain spared when the first two companies were consumed by fire?", choices:["He was not really sent by the king","He fell on his knees and begged Elijah to spare his life and his men's","Elijah had used up his power to call fire","He promised to worship the God of Israel"], a:1, why:"The third captain humbly besought Elijah, asking that his life and the lives of his fifty be precious in his sight, and the angel told Elijah to go down with him without fear." },
      { q:"What does Ahaziah's fate teach about seeking guidance?", choices:["Kings should rely on their own physicians","Any religious source works if sought sincerely","Prophets should never oppose kings","The Lord, not idols or false gods, is the right source for guidance"], a:3, why:"Elijah's rebuke asked why the king sought a foreign god when there was a God in Israel to inquire of, and Ahaziah died exactly as the Lord had said." }
    ] },
  { n:2, summary:"Elisha refuses three times to leave Elijah as they travel from Gilgal to Beth-el, Jericho, and the Jordan, where fifty sons of the prophets watch from afar. Elijah smites the river with his mantle, and the two cross on dry ground. Asked what he desires before Elijah is taken, Elisha asks for a double portion of his spirit, with the condition that he must see his master taken. A chariot of fire with horses of fire parts the two, and Elijah ascends by a whirlwind into heaven. Elisha rends his clothes, takes up the fallen mantle, and parts the Jordan himself; the watching prophets conclude that Elijah's spirit rests on him. He then heals the bitter waters of Jericho with a cruse of salt; on the way to Beth-el, children who mock him are attacked by two she bears; and he goes up to mount Carmel before returning to Samaria.",
    context:"Elijah is taken into heaven and Elisha succeeds him in Israel, witnessed by the sons of the prophets.",
    keyVerses:[
      { ref:"2 Kings 2:9", text:"And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me." },
      { ref:"2 Kings 2:11", text:"And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven." },
      { ref:"2 Kings 2:14", text:"And he took the mantle of Elijah that fell from him, and smote the waters, and said, Where is the LORD God of Elijah? and when he also had smitten the waters, they parted hither and thither: and Elisha went over." }
    ],
    takeaway:"Faithful, persevering service positions us to receive and carry on the spiritual work of those we follow.",
    quiz:[
      { q:"What did Elisha ask of Elijah before Elijah was taken?", choices:["To rule Israel in Elijah's place","To be taken to heaven too","A double portion of Elijah's spirit","To keep Elijah's mantle"], a:2, why:"When Elijah invited him to ask, Elisha requested a double portion of his spirit, which was granted because he saw Elijah taken." },
      { q:"How did the sons of the prophets come to recognize that Elijah's spirit rested on Elisha?", choices:["Elijah appeared to them in a dream","Elisha wore Elijah's cloak in Jericho's streets","They searched three days and found Elijah alive","He smote the Jordan with Elijah's mantle and the waters parted"], a:3, why:"Elisha took up the mantle that fell from Elijah and parted the Jordan as Elijah had done, so the watching prophets bowed before him." },
      { q:"What does Elisha's insistence on staying with Elijah teach about receiving spiritual power?", choices:["Blessings of the Spirit come to those who faithfully stay close to the source God has provided","Spiritual gifts come automatically to those in office","Power can be demanded from God at will","Only miracles prove a prophet's calling"], a:0, why:"Elisha would not leave Elijah at Gilgal, Beth-el, Jericho, or Jordan, and because he persevered to the end he received what he asked." }
    ] },
  { n:3, summary:"Jehoram, Ahab's son, now reigns over Israel; he puts away his father's image of Baal yet clings to the sins of Jeroboam. When Mesha king of Moab rebels and stops his tribute of a hundred thousand lambs and a hundred thousand rams, Jehoram marches against him with Jehoshaphat of Judah and the king of Edom. Seven days into the wilderness of Edom, the armies run out of water. At Jehoshaphat's urging they seek Elisha, who agrees to help only for Judah's king's sake; as a minstrel plays, the Lord's word comes: make the valley full of ditches, and water will come without wind or rain. Morning water red in the sunlight tricks the Moabites into expecting an easy victory, and Israel smites them through their own country — until the king of Moab offers his eldest son upon the wall and the campaign ends.",
    context:"Jehoram son of Ahab rules Israel and allies with Jehoshaphat of Judah and Edom against Moab; the kings seek the prophet Elisha.",
    keyVerses:[
      { ref:"2 Kings 3:15", text:"But now bring me a minstrel. And it came to pass, when the minstrel played, that the hand of the LORD came upon him." },
      { ref:"2 Kings 3:17", text:"For thus saith the LORD, Ye shall not see wind, neither shall ye see rain; yet that valley shall be filled with water, that ye may drink, both ye, and your cattle, and your beasts." },
      { ref:"2 Kings 3:18", text:"And this is but a light thing in the sight of the LORD: he will deliver the Moabites also into your hand." }
    ],
    takeaway:"The Lord honors humble inquiry; He can fill our prepared valleys without wind or rain.",
    quiz:[
      { q:"What did Elisha ask for before the word of the Lord came to him?", choices:["A sacrifice on the altar","A minstrel to play","A bowl of water","The king's crown"], a:1, why:"Elisha said, Bring me a minstrel, and as the minstrel played the hand of the LORD came upon him." },
      { q:"How was water provided for the armies in the wilderness of Edom?", choices:["Ditches dug in the valley filled with water without wind or rain","A spring broke out of the rock","Moab surrendered and opened its wells","Rain clouds gathered overnight"], a:0, why:"The Lord said they would see neither wind nor rain, yet the valley of ditches was filled with water by morning, coming by the way of Edom." },
      { q:"What principle appears in Jehoshaphat's insistence on finding a prophet of the Lord?", choices:["Armies should never ask for help","God helps those who plan well alone","Seeking the Lord's word through His prophet is wise before and during trials","Only kings may receive revelation"], a:2, why:"Jehoshaphat asked whether there was not a prophet of the LORD to inquire by, and deliverance came after Elisha gave the Lord's word." }
    ] },
  { n:4, summary:"Elisha's miracles meet personal needs. A widow of the sons of the prophets faces losing her two sons to a creditor, but her single pot of oil fills every borrowed vessel until none remain, leaving enough to pay the debt and live on. In Shunem a great woman builds a little chamber for Elisha, and by his promise she bears a son. When the boy later dies of a sudden head pain, she rides to mount Carmel and will not leave until Elisha comes; Gehazi's staff fails, but Elisha prays and stretches himself upon the child, who opens his eyes. At Gilgal, meal heals a poisoned pot of pottage, and twenty barley loaves from Baal-shalisha feed a hundred men with food left over, according to the word of the Lord.",
    context:"Elisha ministers in the northern kingdom, helping a prophet's widow, the great woman of Shunem, and the sons of the prophets.",
    keyVerses:[
      { ref:"2 Kings 4:3", text:"Then he said, Go, borrow thee vessels abroad of all thy neighbours, even empty vessels; borrow not a few." },
      { ref:"2 Kings 4:26", text:"Run now, I pray thee, to meet her, and say unto her, Is it well with thee? is it well with thy husband? is it well with the child? And she answered, It is well." },
      { ref:"2 Kings 4:43", text:"And his servitor said, What, should I set this before an hundred men? He said again, Give the people, that they may eat: for thus saith the LORD, They shall eat, and shall leave thereof." }
    ],
    takeaway:"God multiplies small offerings and answers faith that refuses to let go of His help.",
    quiz:[
      { q:"What did the Shunammite woman and her husband prepare for Elisha?", choices:["A festival in the city gate","A flock of sheep","A new chariot","A little chamber on the wall with a bed, table, stool, and candlestick"], a:3, why:"Recognizing him as an holy man of God, she made a little chamber on the wall furnished for his regular visits." },
      { q:"Why did the widow's oil stop flowing?", choices:["Elisha canceled the miracle","The pot broke","She ran out of vessels to fill","Her sons lost faith"], a:2, why:"The oil stayed only when her son reported there was not a vessel more; the supply matched the preparation of faith." },
      { q:"What do the raising of the Shunammite's son, the healed pottage, and the multiplied loaves show about the Lord?", choices:["He acts only when prophets are paid","He cares about the daily needs and griefs of the faithful","Miracles ended with Elijah","Faith removes all trials from life"], a:1, why:"The chapter ties the Lord's power to a widow's debt, a dead child, a poisoned meal, and hungry students, showing His concern for ordinary needs." }
    ] },
  { n:5, summary:"Naaman, captain of Syria's host and a mighty man of valor, is a leper. A little Israelite captive serving his wife points him to the prophet in Samaria, and Naaman comes with a royal letter, ten talents of silver, and rich gifts. Israel's king reads the request as a trap and rends his clothes, but Elisha sends for the general — only to meet him with a messenger's instruction to wash seven times in the Jordan. Angry that no prophet came out, called on the Lord, or waved a hand over him, and scorning Israel's rivers, Naaman storms off until his servants reason with him. Washing as told, he is cleansed and confesses there is no God in all the earth but in Israel. Elisha refuses a reward, but Gehazi runs after the gifts, lies to cover it, and leaves a leper.",
    context:"Naaman, army captain of Syria, seeks healing from Elisha in Samaria while Syria and Israel are uneasy neighbors.",
    keyVerses:[
      { ref:"2 Kings 5:10", text:"And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean." },
      { ref:"2 Kings 5:15", text:"And he returned to the man of God, he and all his company, and came, and stood before him: and he said, Behold, now I know that there is no God in all the earth, but in Israel: now therefore, I pray thee, take a blessing of thy servant." },
      { ref:"2 Kings 5:27", text:"The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow." }
    ],
    takeaway:"Simple obedience, even when it seems beneath us, opens the way to God's cleansing power.",
    quiz:[
      { q:"How many times was Naaman told to wash in the Jordan?", choices:["Seven times","Three times","Twelve times","Once"], a:0, why:"Elisha's messenger commanded him to go and wash in Jordan seven times, promising that his flesh would come again and he would be clean." },
      { q:"What finally persuaded Naaman to obey the prophet's simple instruction?", choices:["A decree from the king of Israel","The gifts he had brought","A vision in the night","His servants reasoned that he would have done a great thing if asked, so he should do the easy thing"], a:3, why:"His servants asked whether he would not have done some great thing if the prophet had asked it, and how much rather to wash and be clean." },
      { q:"What does Naaman's healing teach about how the Lord works?", choices:["He heals only Israelites","Blessings require expensive offerings","Obedience to prophetic counsel, however simple, brings the Lord's power","Rivers in one's homeland are equally effective"], a:2, why:"Naaman expected a dramatic display, but cleansing came through humble compliance with the prophet's word, and he confessed Israel's God as the only God." }
    ] },
  { n:6, summary:"When a borrowed axe head sinks in the Jordan as the sons of the prophets enlarge their dwelling, Elisha casts in a stick, and the iron swims. He then warns Israel's king of Syria's planned ambushes so often that Ben-hadad suspects a traitor — and learns that Elisha hears even the words spoken in his bedchamber. A great host surrounds Dothan by night; Elisha's terrified servant sees the mountain full of horses and chariots of fire once his eyes are opened. The Syrians are smitten with blindness, led into Samaria, fed a great provision, and sent home, so the bands of Syria raid no more. But Ben-hadad then besieges Samaria itself, and famine drives two women to a dreadful bargain. The grieving king, sackcloth beneath his robe, vows to have Elisha's head — yet the prophet already knows his approach.",
    context:"Elisha serves Israel's king against Syrian raids; then Ben-hadad of Syria besieges Samaria amid great famine.",
    keyVerses:[
      { ref:"2 Kings 6:6", text:"And the man of God said, Where fell it? And he shewed him the place. And he cut down a stick, and cast it in thither; and the iron did swim." },
      { ref:"2 Kings 6:16", text:"And he answered, Fear not: for they that be with us are more than they that be with them." },
      { ref:"2 Kings 6:22", text:"And he answered, Thou shalt not smite them: wouldest thou smite those whom thou hast taken captive with thy sword and with thy bow? set bread and water before them, that they may eat and drink, and go to their master." }
    ],
    takeaway:"God's unseen help is greater than any army set against the faithful.",
    quiz:[
      { q:"Where was Elisha living when the Syrian army surrounded the city at night?", choices:["Jericho","Dothan","Samaria","Mount Carmel"], a:1, why:"Ben-hadad learned that Elisha was in Dothan and sent horses, chariots, and a great host to encircle it by night." },
      { q:"Why did Elisha tell his frightened servant not to fear?", choices:["The Syrians were unarmed","The river would stop the army","Those with them were more than those with the enemy","The king's army had just arrived"], a:2, why:"After Elisha prayed for his eyes to be opened, the young man saw the mountain full of horses and chariots of fire round about Elisha." },
      { q:"What principle guided Elisha's treatment of the captured Syrians?", choices:["Mercy toward captured enemies can end conflict better than bloodshed","Captives must always be ransomed","Enemies should be enslaved","Prophets should lead armies personally"], a:0, why:"Elisha told the king to set bread and water before them and send them home, and the bands of Syria came no more into the land." }
    ] },
  { n:7, summary:"Elisha answers the king's despair with a promise: by tomorrow about this time, fine flour and barley will sell cheap in Samaria's gate. The courtier on whom the king leaned scoffs that not even windows opened in heaven could do such a thing, and is told he will see it but not eat of it. Four leprous men at the gate decide that sitting still means dying, so they walk into the Syrian camp. The Lord has made the Syrians hear a noise of chariots and a great host, and they flee at twilight, leaving tents, horses, and spoil. After eating and hiding treasure, the lepers admit they do not well to hold their peace on a day of good tidings, and they report to the city. After a cautious scout, the people spoil the camp — prices collapse overnight, and the scoffing courtier is trampled in the gate.",
    context:"Famine-stricken Samaria is still besieged by Syria when Elisha promises overnight relief, which four lepers discover first.",
    keyVerses:[
      { ref:"2 Kings 7:1", text:"Then Elisha said, Hear ye the word of the LORD; Thus saith the LORD, To morrow about this time shall a measure of fine flour be sold for a shekel, and two measures of barley for a shekel, in the gate of Samaria." },
      { ref:"2 Kings 7:9", text:"Then they said one to another, We do not well: this day is a day of good tidings, and we hold our peace: if we tarry till the morning light, some mischief will come upon us: now therefore come, that we may go and tell the king's household." },
      { ref:"2 Kings 7:20", text:"And so it fell out unto him: for the people trode upon him in the gate, and he died." }
    ],
    takeaway:"When the Lord provides deliverance, believers must share the good tidings, not hoard them.",
    quiz:[
      { q:"Who first discovered that the Syrian camp had been abandoned?", choices:["The king's watchmen","The porters at the gate","Four leprous men at the gate","Elisha's servant Gehazi"], a:2, why:"Four leprous men at the entering in of the gate reasoned they had nothing to lose and walked into the emptied Syrian camp." },
      { q:"Why did the Syrians flee their camp?", choices:["The Lord made them hear a noise of chariots and a great host","Their food ran out","Israel attacked by night","A storm scattered them"], a:0, why:"The Lord made the host of Syria hear a noise of chariots and horses, and they concluded Israel had hired the kings of the Hittites and Egyptians against them." },
      { q:"What principle did the lepers act on after finding the abandoned camp?", choices:["Wealth should be hidden quickly","Suffering is punishment for sin","Only priests may announce news","Good news must be shared, not kept silent until morning"], a:3, why:"They admitted it was not well to hold their peace on a day of good tidings and went to tell the king's household." }
    ] },
  { n:8, summary:"Elisha tells the Shunammite woman whose son he restored that a seven-year famine is coming, and she sojourns in the land of the Philistines. Returning at the famine's end, she appeals to the king for her house and land just as Gehazi is describing to the king how Elisha raised her son — and she leaves with everything restored, including the fruits of seven years. In Damascus, sick Ben-hadad sends Hazael to ask Elisha whether he will recover. Elisha answers that he may recover, yet the Lord has shown that he will surely die, and weeps over the evil Hazael will do to Israel — strong holds burned, young men slain. Revealed as Syria's next king, Hazael returns with a comforting half-answer and spreads a water-soaked cloth on the king's face, so that he dies. Judah's Jehoram, married to Ahab's daughter, then walks in Ahab's ways and loses Edom.",
    context:"Elisha's dealings span both kingdoms: the Shunammite restored in Israel, Hazael rising in Syria, and Ahab's line now tied to Judah's throne.",
    keyVerses:[
      { ref:"2 Kings 8:1", text:"Then spake Elisha unto the woman, whose son he had restored to life, saying, Arise, and go thou and thine household, and sojourn wheresoever thou canst sojourn: for the LORD hath called for a famine; and it shall also come upon the land seven years." },
      { ref:"2 Kings 8:6", text:"And when the king asked the woman, she told him. So the king appointed unto her a certain officer, saying, Restore all that was hers, and all the fruits of the field since the day that she left the land, even until now." },
      { ref:"2 Kings 8:13", text:"And Hazael said, But what, is thy servant a dog, that he should do this great thing? And Elisha answered, The LORD hath shewed me that thou shalt be king over Syria." }
    ],
    takeaway:"Counsel from the Lord's prophet, followed in faith, preserves us and can restore what hard years take away.",
    quiz:[
      { q:"How long would the famine Elisha foretold last?", choices:["Three years","Forty days","One year","Seven years"], a:3, why:"Elisha told the Shunammite the LORD had called for a famine that would come upon the land seven years." },
      { q:"Why did the king restore the Shunammite's land and income?", choices:["Jehoshaphat advised him to","Gehazi was telling him of Elisha's miracles just as she arrived to appeal","She paid him a large bribe","The law required it after seven years"], a:1, why:"As Gehazi told the king how Elisha had raised a dead son to life, the very woman and her son appeared, and the king appointed an officer to restore all that was hers." },
      { q:"What does the Shunammite's seven-year sojourn teach about following prophetic counsel?", choices:["Obedience to a prophet's warning preserves a family through hard times","Moving abroad guarantees prosperity","Prophetic warnings are optional suggestions","Land claims are always lost during famines"], a:0, why:"She acted at once on Elisha's word, and when she returned the Lord opened the way for her house and land to be restored with the fruits of seven years." }
    ] },
  { n:9, summary:"Elisha sends a young prophet to Ramoth-gilead with a box of oil. There he anoints Jehu, captain of the host, king over Israel and commissions him to smite the house of Ahab, avenging the blood of the Lord's servants at the hand of Jezebel. The army commanders crown Jehu immediately, blowing trumpets, and he races toward Jezreel, where wounded Joram lies and Ahaziah of Judah visits him. Asked whether he comes in peace, Jehu replies that there is no peace while Jezebel's whoredoms and witchcrafts are so many, then shoots Joram through the heart in the portion of Naboth the Jezreelite — the very ground where the Lord said Naboth's blood would be requited. Ahaziah flees, is smitten at Gur, and dies at Megiddo. Jezebel, painted and looking from her window, is thrown down and left without burial, as Elijah had spoken.",
    context:"Elisha sends a young prophet to anoint Jehu king over Israel; Ahaziah of Judah is caught at Jezreel beside wounded Joram.",
    keyVerses:[
      { ref:"2 Kings 9:6", text:"And he arose, and went into the house; and he poured the oil on his head, and said unto him, Thus saith the LORD God of Israel, I have anointed thee king over the people of the LORD, even over Israel." },
      { ref:"2 Kings 9:22", text:"And it came to pass, when Joram saw Jehu, that he said, Is it peace, Jehu? And he answered, What peace, so long as the whoredoms of thy mother Jezebel and her witchcrafts are so many?" },
      { ref:"2 Kings 9:36", text:"Wherefore they came again, and told him. And he said, This is the word of the LORD, which he spake by his servant Elijah the Tishbite, saying, In the portion of Jezreel shall dogs eat the flesh of Jezebel:" }
    ],
    takeaway:"The Lord fulfills every word spoken by His servants, in mercy and in judgment alike.",
    quiz:[
      { q:"Who actually poured the anointing oil on Jehu's head?", choices:["A young prophet sent by Elisha","Elisha himself","Jehonadab the son of Rechab","A priest of Jezreel"], a:0, why:"Elisha called one of the children of the prophets, gave him a box of oil, and sent him to Ramoth-gilead to anoint Jehu and flee." },
      { q:"Why was Joram slain in the portion of Naboth the Jezreelite?", choices:["Jehu owned that field","It was the nearest battlefield","To requite the blood of Naboth and his sons, as the Lord had spoken","Joram refused to fight there"], a:2, why:"Jehu reminded Bidkar that the Lord had said He would requite Ahab's house in the plot where Naboth's blood had been shed." },
      { q:"What does Jezebel's end confirm about prophetic words?", choices:["Prophecies apply only to their own day","Every word the Lord speaks through His prophets is fulfilled","Dogs were sacred in Israel","Royal power can override prophecy"], a:1, why:"Jehu noted that her unburied remains fulfilled the very word the Lord spoke by Elijah, that dogs would eat Jezebel in the portion of Jezreel." }
    ] },
  { n:10, summary:"Jehu consolidates the purge. In letters he dares Samaria's rulers to set one of Ahab's seventy sons on the throne; terrified, they instead send him the heads of all seventy, and Jehu tells the people that nothing of the Lord's word concerning Ahab's house can fall to the ground. He destroys the rest of Ahab's house, his great men, kinsfolk, and priests, and on the road kills forty-two of Ahaziah's brethren. With Jehonadab the son of Rechab riding beside him, he gathers every worshipper of Baal into Baal's temple under pretext of a great sacrifice, has eighty men cut them down, breaks the images, and makes Baal's house a draught house — thus Jehu destroyed Baal out of Israel. Yet he departs not from the golden calves of Jeroboam. For executing the Lord's judgment on Ahab his line is promised four generations, but the Lord begins to cut Israel short by Hazael's hand.",
    context:"Jehu, now king of Israel, executes judgment on Ahab's dynasty and Baal worship yet keeps Jeroboam's golden calves.",
    keyVerses:[
      { ref:"2 Kings 10:10", text:"Know now that there shall fall unto the earth nothing of the word of the LORD, which the LORD spake concerning the house of Ahab: for the LORD hath done that which he spake by his servant Elijah." },
      { ref:"2 Kings 10:30", text:"And the LORD said unto Jehu, Because thou hast done well in executing that which is right in mine eyes, and hast done unto the house of Ahab according to all that was in mine heart, thy children of the fourth generation shall sit on the throne of Israel." },
      { ref:"2 Kings 10:31", text:"But Jehu took no heed to walk in the law of the LORD God of Israel with all his heart: for he departed not from the sins of Jeroboam, which made Israel to sin." }
    ],
    takeaway:"Zeal against evil is not enough; the Lord requires wholehearted obedience to His law.",
    quiz:[
      { q:"How many of Ahab's sons were slain in Samaria at Jehu's demand?", choices:["Twelve","Seventy","Forty-two","Twenty"], a:1, why:"Ahab had seventy sons in Samaria, and the city's rulers, fearing Jehu, slew all seventy and sent their heads to Jezreel." },
      { q:"How did Jehu destroy Baal worship in Israel?", choices:["He taxed Baal's priests until they left the land","He debated the prophets publicly and won","He burned the golden calves at Beth-el and Dan","He lured all Baal's worshippers into Baal's temple with a pretended feast, slew them, and razed it"], a:3, why:"By subtilty he proclaimed a solemn assembly for Baal, filled the temple with worshippers, and had his guards slay them and demolish the image and the house." },
      { q:"What shortcoming kept Jehu's dynasty from full blessing?", choices:["He refused to anoint a successor","He kept Ahab's daughters in the palace","He never departed from the sins of Jeroboam, the golden calves","He taxed the people heavily"], a:2, why:"Though promised four generations for executing judgment on Ahab's house, Jehu took no heed to walk in the law of the LORD with all his heart." }
    ] },
  { n:11, summary:"When Athaliah, mother of the dead king Ahaziah, destroys all the seed royal of Judah, Jehosheba — the king's sister — steals away the infant Joash and hides him and his nurse in the house of the Lord for six years while Athaliah reigns. In the seventh year the priest Jehoiada covenants with the rulers over hundreds and the guard, stations them around the temple, and arms them with David's spears and shields. The king's son is brought forth, crowned, given the testimony, anointed, and acclaimed. Athaliah cries Treason, but is put forth from the house of the Lord and slain apart from the sanctuary. Jehoiada makes a covenant that the king and people should be the Lord's people; Baal's house is broken down and its priest slain; and the city is quiet under seven-year-old Jehoash.",
    context:"In Judah, queen Athaliah reigns after killing the royal seed, until the priest Jehoiada crowns the hidden heir Joash.",
    keyVerses:[
      { ref:"2 Kings 11:2", text:"But Jehosheba, the daughter of king Joram, sister of Ahaziah, took Joash the son of Ahaziah, and stole him from among the king's sons which were slain; and they hid him, even him and his nurse, in the bedchamber from Athaliah, so that he was not slain." },
      { ref:"2 Kings 11:12", text:"And he brought forth the king's son, and put the crown upon him, and gave him the testimony; and they made him king, and anointed him; and they clapped their hands, and said, God save the king." },
      { ref:"2 Kings 11:17", text:"And Jehoiada made a covenant between the LORD and the king and the people, that they should be the LORD's people; between the king also and the people." }
    ],
    takeaway:"One righteous, courageous soul can preserve God's covenant people and restore true worship.",
    quiz:[
      { q:"How old was Joash when Jehoiada brought him forth and crowned him?", choices:["Twelve","Sixteen","Seven","Three"], a:2, why:"After six years hidden in the house of the LORD, Joash was seven years old when he began to reign." },
      { q:"Why did Athaliah cry, Treason, Treason, in the temple?", choices:["The guards had emptied the treasury","The rightful heir she thought she had destroyed was being crowned","Jehoiada refused her a sacrifice","The people demanded her as queen"], a:1, why:"She saw the king standing by a pillar with the princes and trumpeters, and all the people rejoicing, over the boy she believed dead." },
      { q:"What does the account of Joash's preservation teach about God's purposes?", choices:["God cannot work through unlikely people","Royal bloodlines fail without armies","Political power alone preserves the covenant","The Lord preserves His covenant line and can use faithful individuals to do it"], a:3, why:"Jehosheba's courage and Jehoiada's covenant faithfulness kept the royal line alive against Athaliah's slaughter of the seed royal." }
    ] },
  { n:12, summary:"Jehoash reigns forty years in Jerusalem, doing right all his days while Jehoiada the priest instructs him, though the high places remain. Wanting the breaches of the temple repaired, he first directs the priests to take the dedicated money for that work; after twenty-three years nothing is done, so the priests are released from the task and Jehoiada sets a chest with a hole in its lid beside the altar. Counted money passes directly to carpenters, masons, and buyers of timber and hewn stone, who deal so faithfully that no audit is required, though no silver vessels are made from it. When Hazael of Syria takes Gath and turns toward Jerusalem, Jehoash empties the temple's and palace's hallowed treasures to buy him off. Later his own servants conspire against him and slay him at Millo, and Amaziah his son reigns.",
    context:"Joash (Jehoash) rules Judah under the guiding influence of Jehoiada the priest while Hazael of Syria threatens the land.",
    keyVerses:[
      { ref:"2 Kings 12:2", text:"And Jehoash did that which was right in the sight of the LORD all his days wherein Jehoiada the priest instructed him." },
      { ref:"2 Kings 12:15", text:"Moreover they reckoned not with the men, into whose hand they delivered the money to be bestowed on workmen: for they dealt faithfully." },
      { ref:"2 Kings 12:18", text:"And Jehoash king of Judah took all the hallowed things that Jehoshaphat, and Jehoram, and Ahaziah, his fathers, kings of Judah, had dedicated, and his own hallowed things, and all the gold that was found in the treasures of the house of the LORD, and in the king's house, and sent it to Hazael king of Syria: and he went away from Jerusalem." }
    ],
    takeaway:"Under faithful guidance even a young king can do right, and sacred work prospers in honest hands.",
    quiz:[
      { q:"What did Jehoiada set beside the altar to collect repair money?", choices:["A chest with a hole bored in the lid","A bronze trumpet","A balance scale","A golden urn"], a:0, why:"The priest took a chest, bored a hole in its lid, and set it beside the altar, and the doorkeepers put in all the money brought into the house of the LORD." },
      { q:"Why did Jehoash send the temple's hallowed treasures to Hazael?", choices:["To fund new temple vessels","To pay Jehoiada's priesthood","As tribute demanded after he conquered Assyria","To buy off Hazael, who had taken Gath and set his face toward Jerusalem"], a:3, why:"Facing the Syrian threat after Gath fell, the king gave the sacred and palace gold to Hazael, who then went away from Jerusalem." },
      { q:"What made the temple repair fund effective?", choices:["The priests' preaching","Honest accounting and faithful workmen who were trusted without audit","Royal taxation of every city","Foreign donations"], a:1, why:"No reckoning was made with the workmen because they dealt faithfully; the money went straight to builders and materials for the breaches." }
    ] },
  { n:13, summary:"Under Jehoahaz, Israel does evil and is ground down by Hazael and Ben-hadad of Syria until only fifty horsemen, ten chariots, and ten thousand footmen remain; when the king beseeches the Lord, a saviour grants relief, yet the golden calves and the grove remain. His son Jehoash weeps over dying Elisha, calling him the chariot of Israel. Given a bow and an arrow of the Lord's deliverance promised over Syria at Aphek, Jehoash is told to smite the ground with the arrows; he strikes three times and stops, and the provoked prophet limits his triumph to three victories. Elisha dies and is buried, but a dead man cast into his sepulchre revives when his body touches the prophet's bones. Because of His covenant with Abraham, Isaac, and Jacob, the Lord remains gracious, and Joash recovers the cities Syria had taken, beating Ben-hadad three times.",
    context:"Syria oppresses Israel under Jehoahaz and Jehoash; Elisha dies during the reign of Israel's king Joash.",
    keyVerses:[
      { ref:"2 Kings 13:4", text:"And Jehoahaz besought the LORD, and the LORD hearkened unto him: for he saw the oppression of Israel, because the king of Syria oppressed them." },
      { ref:"2 Kings 13:19", text:"And the man of God was wroth with him, and said, Thou shouldest have smitten five or six times; then hadst thou smitten Syria till thou hadst consumed it: whereas now thou shalt smite Syria but thrice." },
      { ref:"2 Kings 13:23", text:"And the LORD was gracious unto them, and had compassion on them, and had respect unto them, because of his covenant with Abraham, Isaac, and Jacob, and would not destroy them, neither cast he them from his presence as yet." }
    ],
    takeaway:"Halfhearted effort limits the blessings God can give; wholehearted seeking invites full deliverance.",
    quiz:[
      { q:"How many times did king Joash smite the ground with the arrows?", choices:["Once","Five times","Seven times","Three times"], a:3, why:"Told to smite upon the ground, he smote thrice and stayed, and Elisha said he should have smitten five or six times." },
      { q:"What did Elisha's limited number of smites mean for Israel's victory over Syria?", choices:["Joash would smite Syria only three times instead of consuming it","Syria would win three battles","Three prophets would arise","The arrow was meaningless"], a:0, why:"Elisha explained that fuller striking would have consumed Syria; now the deliverance was limited to three victories, which Joash achieved over Ben-hadad." },
      { q:"Why does the historian note that a dead man revived at Elisha's tomb?", choices:["To prove Elisha honored Israel's king","To explain the Moabite raids","Even after death, the Lord's power with His servant continued","To describe burial customs"], a:2, why:"A dead man cast into Elisha's sepulchre revived at the touch of his bones, and the Lord remained gracious for the covenant with Abraham, Isaac, and Jacob." }
    ] },
  { n:14, summary:"Amaziah of Judah does right, though not like David, sparing the children of his father's executioners according to the law of Moses, and he smites ten thousand of Edom in the valley of salt, taking Selah and naming it Joktheel. Puffed up by that victory, he challenges Jehoash of Israel, who answers with the parable of a thistle demanding a cedar's daughter and being crushed by a wild beast: glory in Edom, but tarry at home. Amaziah will not hear; Judah is routed at Beth-shemesh, Jerusalem's wall is broken down four hundred cubits, and temple and palace treasures go to Samaria. Years later Amaziah flees a conspiracy to Lachish and is slain; his son Azariah, sixteen, succeeds him. In Israel, Jeroboam II reigns forty-one years; though he does evil, he restores Israel's coast, for the Lord, by the word of Jonah, will not yet blot out Israel's name.",
    context:"Amaziah and then Azariah rule Judah while Jehoash and Jeroboam II rule Israel; the two kingdoms clash at Beth-shemesh.",
    keyVerses:[
      { ref:"2 Kings 14:6", text:"But the children of the murderers he slew not: according unto that which is written in the book of the law of Moses, wherein the LORD commanded, saying, The fathers shall not be put to death for the children, nor the children be put to death for the fathers; but every man shall be put to death for his own sin." },
      { ref:"2 Kings 14:10", text:"Thou hast indeed smitten Edom, and thine heart hath lifted thee up: glory of this, and tarry at home: for why shouldest thou meddle to thy hurt, that thou shouldest fall, even thou, and Judah with thee?" },
      { ref:"2 Kings 14:27", text:"And the LORD said not that he would blot out the name of Israel from under heaven: but he saved them by the hand of Jeroboam the son of Joash." }
    ],
    takeaway:"Victory can breed pride; the Lord warns the prosperous to stay humble or fall.",
    quiz:[
      { q:"What city did Amaziah take from Edom and rename Joktheel?", choices:["Lachish","Selah","Gath","Beth-shemesh"], a:1, why:"After slaying ten thousand of Edom in the valley of salt, he took Selah by war and called the name of it Joktheel." },
      { q:"What was the point of Jehoash's thistle-and-cedar parable?", choices:["Judah should intermarry with Israel","Edom would rebel again","Pride after a minor victory invites a crushing fall","Fortresses in Lebanon were weak"], a:2, why:"Jehoash warned Amaziah that his heart was lifted up by smiting Edom and that meddling would bring him and Judah down; Judah was then defeated at Beth-shemesh." },
      { q:"What does Jeroboam II's successful reign despite his evil show about the Lord?", choices:["The Lord approves political success","Israel's armies were unmatched","Evil never matters in history","The Lord kept covenant mercy, refusing for a time to blot out Israel's name"], a:3, why:"The Lord saw Israel's bitter affliction and saved them by Jeroboam's hand, restoring the coast according to the word spoken by Jonah the prophet." }
    ] },
  { n:15, summary:"Azariah (Uzziah) reigns fifty-two years in Jerusalem, doing right like his father yet leaving the high places, until the Lord smites him with leprosy and Jotham his son judges the land. Israel meanwhile lurches from king to king: Zachariah holds the throne six months, ending Jehu's dynasty at the promised fourth generation; Shallum lasts a full month before Menahem kills him and brutally sacks resistant Tiphsah; Menahem pays Pul of Assyria a thousand talents of silver, levied from the wealthy, to confirm his kingdom; captain Pekah murders Pekahiah after two years; and under Pekah, Tiglath-pileser carries Gilead, Galilee, and all Naphtali captive to Assyria before Hoshea conspires against him. In Judah, Jotham does right and builds the higher gate, though the high places remain — and in those days the Lord begins to send against Judah Rezin of Syria and Pekah of Israel.",
    context:"Azariah's long reign in Judah contrasts with a string of assassinated kings in Israel as Assyria first seizes Israelite territory.",
    keyVerses:[
      { ref:"2 Kings 15:5", text:"And the LORD smote the king, so that he was a leper unto the day of his death, and dwelt in a several house. And Jotham the king's son was over the house, judging the people of the land." },
      { ref:"2 Kings 15:12", text:"This was the word of the LORD which he spake unto Jehu, saying, Thy sons shall sit on the throne of Israel unto the fourth generation. And so it came to pass." },
      { ref:"2 Kings 15:29", text:"In the days of Pekah king of Israel came Tiglath-pileser king of Assyria, and took Ijon, and Abel-beth-maachah, and Janoah, and Kedesh, and Hazor, and Gilead, and Galilee, all the land of Naphtali, and carried them captive to Assyria." }
    ],
    takeaway:"Kings and kingdoms rise and fall, but every word of the Lord comes to pass.",
    quiz:[
      { q:"How long did Azariah (Uzziah) reign in Jerusalem, and how did his life end?", choices:["Ten years, exiled","Sixteen years, in war","Fifty-two years, a leper in a several house","Forty years, on the battlefield"], a:2, why:"He reigned two and fifty years, did right though not removing the high places, until the LORD smote him with leprosy unto the day of his death." },
      { q:"What older prophecy did Zachariah's brief reign fulfill?", choices:["Jehu's sons would sit on Israel's throne to the fourth generation","Israel would be carried to Assyria","A prophet would die at Beth-el","Jeroboam's dynasty would last forever"], a:0, why:"Shallum's assassination of Zachariah ended Jehu's house exactly at the fourth generation, as the word of the LORD to Jehu said it would." },
      { q:"What does the string of violent successions in Israel illustrate?", choices:["Assassination was an accepted transfer of power","Unfaithfulness to the Lord brings instability and weakness to a nation","Assyria supported reforms in Israel","Judah's kings ruled Israel directly"], a:1, why:"Ruler after ruler departed not from the sins of Jeroboam and fell to conspirators, and Tiglath-pileser began carrying Israel's land away captive." }
    ] },
  { n:16, summary:"Ahaz of Judah walks in the way of the kings of Israel, makes his son pass through the fire, and sacrifices in high places under every green tree. When Rezin of Syria and Pekah of Israel besiege Jerusalem but cannot overcome it, Ahaz strips silver and gold from the temple and palace and appeals to Tiglath-pileser of Assyria: I am thy servant and thy son — come up and save me. Assyria takes Damascus, slays Rezin, and carries its people captive to Kir. Visiting Damascus, Ahaz admires the pagan altar there and has Urijah the priest build its likeness in Jerusalem before he returns. He offers on the new altar, pushes the brasen altar aside for his own inquiries, and alters other temple furnishings for the king of Assyria's sake. Hezekiah his son follows him.",
    context:"Ahaz of Judah, attacked by Syria and Israel, turns to Assyria for rescue and refashions temple worship after a foreign pattern.",
    keyVerses:[
      { ref:"2 Kings 16:3", text:"But he walked in the way of the kings of Israel, yea, and made his son to pass through the fire, according to the abominations of the heathen, whom the LORD cast out from before the children of Israel." },
      { ref:"2 Kings 16:7", text:"So Ahaz sent messengers to Tiglath-pileser king of Assyria, saying, I am thy servant and thy son: come up, and save me out of the hand of the king of Syria, and out of the hand of the king of Israel, which rise up against me." },
      { ref:"2 Kings 16:10", text:"And king Ahaz went to Damascus to meet Tiglath-pileser king of Assyria, and saw an altar that was at Damascus: and king Ahaz sent to Urijah the priest the fashion of the altar, and the pattern of it, according to all the workmanship thereof." }
    ],
    takeaway:"Trusting the arm of the world instead of the Lord corrupts both worship and the heart.",
    quiz:[
      { q:"To whom did Ahaz turn for rescue from Syria and Israel?", choices:["Tiglath-pileser king of Assyria","Pharaoh of Egypt","The king of Moab","Jehoash of Israel"], a:0, why:"Ahaz sent messengers to Tiglath-pileser, calling himself his servant and son, and sent the silver and gold of temple and palace." },
      { q:"What did Ahaz do after seeing the altar at Damascus?", choices:["He destroyed it as an idol","He had Urijah the priest build a copy in Jerusalem and offered on it","He brought Rezin's priests to Judah","He wrote a law against altars"], a:1, why:"Ahaz sent the altar's pattern to Urijah, who built it before the king returned; Ahaz then offered on it and moved aside the brasen altar of the LORD." },
      { q:"What does Ahaz's reign show about seeking deliverance from ungodly powers?", choices:["Alliances guarantee safety","Temple treasures are safest abroad","Leaning on worldly power can pull worship itself away from the Lord","Assyria worshipped the God of Israel"], a:2, why:"Saved by Assyria, Ahaz reshaped the Lord's altar and temple fittings for the king of Assyria's sake, walking in the abominations of the heathen." }
    ] },
  { n:17, summary:"Hoshea, Israel's last king, serves Shalmaneser of Assyria until a secret message to Egypt lands him in prison; after a three-year siege, Samaria falls in Hoshea's ninth year, and Israel is carried to Halah, Habor by the river of Gozan, and the cities of the Medes. The historian then explains the fall at length: Israel sinned against the God who brought them up from Egypt, feared other gods, walked in the heathen statutes, built high places in every city, set up images and groves, made two calves, worshipped the host of heaven, served Baal, made their children pass through fire, and sold themselves to do evil. Yet the Lord testified against Israel and Judah by all the prophets, commanding them to turn from their evil ways; they hardened their necks and would not hear. So the Lord removed Israel out of His sight, leaving Judah alone — and Judah walked in Israel's statutes too. Resettled foreigners learn only a mixed fear of the Lord.",
    context:"Israel's northern kingdom falls to Assyria; the historian's overview explains the exile as judgment for generations of unheeded warnings.",
    keyVerses:[
      { ref:"2 Kings 17:13", text:"Yet the LORD testified against Israel, and against Judah, by all the prophets, and by all the seers, saying, Turn ye from your evil ways, and keep my commandments and my statutes, according to all the law which I commanded your fathers, and which I sent to you by my servants the prophets." },
      { ref:"2 Kings 17:18", text:"Therefore the LORD was very angry with Israel, and removed them out of his sight: there was none left but the tribe of Judah only." },
      { ref:"2 Kings 17:33", text:"They feared the LORD, and served their own gods, after the manner of the nations whom they carried away from thence." }
    ],
    takeaway:"The Lord pleads through prophets before He punishes; rejecting their warnings ends in loss.",
    quiz:[
      { q:"Which empire conquered and deported the northern kingdom?", choices:["Egypt","Babylon","Rome","Assyria"], a:3, why:"Shalmaneser king of Assyria besieged Samaria three years, and in the ninth year of Hoshea the Assyrian king carried Israel away to Halah, Habor, Gozan, and the cities of the Medes." },
      { q:"According to this chapter, what was the root cause of Israel's fall?", choices:["A weak army and dry winters","The loss of the ark of the covenant","Sinning against the Lord and refusing the warnings of every prophet He sent","Overpopulation in Samaria"], a:2, why:"Israel served other gods, walked in heathen statutes, and would not hear, though the LORD testified against them to turn from their evil ways." },
      { q:"What is the meaning of the Lord testifying by all the prophets before judgment falls?", choices:["The Lord always warns His people through His servants before He acts","Prophets speak only after disasters","Warnings apply to other nations only","Judgment comes without notice"], a:0, why:"The Lord testified against Israel and Judah, saying Turn ye from your evil ways; refusing to hear, they hardened their necks and fell." }
    ] },
  { n:18, summary:"Hezekiah begins to reign in Judah and does right like David: he removes the high places, breaks the images, cuts down the groves, and even shatters the brasen serpent Moses had made, since Israel burned incense to it. He trusts the Lord as no king of Judah before or after him, cleaves to the commandments, prospers, rebels against Assyria, and smites the Philistines. During his reign Samaria falls, carrying Israel into Assyrian exile for its disobedience. In his fourteenth year Sennacherib takes all Judah's fenced cities; Hezekiah pays the demanded three hundred talents of silver and thirty of gold, even stripping the temple doors. Assyria still comes: by the conduit of the upper pool, Rab-shakeh mocks Egypt as a bruised reed, twists Hezekiah's removal of the high places as an offense against the Lord, and shouts to the men on the wall that no god of any nation has ever delivered his land from Assyria. By the king's command the people answer him not a word.",
    context:"Hezekiah's reform in Judah provokes Assyria's retaliation; Sennacherib's envoy Rab-shakeh mocks trust in the Lord outside Jerusalem's wall.",
    keyVerses:[
      { ref:"2 Kings 18:5", text:"He trusted in the LORD God of Israel; so that after him was none like him among all the kings of Judah, nor any that were before him." },
      { ref:"2 Kings 18:35", text:"Who are they among all the gods of the countries, that have delivered their country out of mine hand, that the LORD should deliver Jerusalem out of mine hand?" },
      { ref:"2 Kings 18:36", text:"But the people held their peace, and answered him not a word: for the king's commandment was, saying, Answer him not." }
    ],
    takeaway:"Even when mockery surrounds us, trusting the Lord is never misplaced confidence.",
    quiz:[
      { q:"What object of Moses' day did Hezekiah destroy because Israel burned incense to it?", choices:["The ark of the covenant","The brasen serpent","The table of shewbread","Aaron's rod"], a:1, why:"He brake in pieces the brasen serpent that Moses had made, calling it Nehushtan, because the children of Israel burned incense to it." },
      { q:"How did Rab-shakeh twist Hezekiah's reforms in his speech?", choices:["He claimed removing the high places proved Hezekiah insulted the Lord","He said Hezekiah worshipped too many gods","He denied Hezekiah ever ruled Judah","He accused Hezekiah of allying with Assyria"], a:0, why:"Rab-shakeh argued that the Lord, whose high places and altars Hezekiah had taken away, could not be expected to deliver Jerusalem." },
      { q:"How should believers respond to mockery of their faith, as this chapter shows?", choices:["Trade insults with the mockers","Abandon reforms to appease enemies","Stay silent on command and take the matter to the Lord and His prophet","Flee to Egypt for safety"], a:2, why:"The people held their peace and answered not a word, as Hezekiah commanded, while he turned in grief to the Lord through Isaiah." }
    ] },
  { n:19, summary:"Hearing the Assyrian taunts, Hezekiah rents his clothes, covers himself with sackcloth, and goes into the house of the Lord, sending to Isaiah: this day is a day of trouble, rebuke, and blasphemy; lift up thy prayer for the remnant. Isaiah answers that Sennacherib will hear a rumour, return, and fall by the sword in his land. As Rab-shakeh returns, Sennacherib is found fighting Libnah, and a threatening letter arrives with news of Tirhakah's advance; Hezekiah spreads it before the Lord in the temple and prays that all kingdoms may know that the Lord alone is God, who made heaven and earth. Isaiah sends the Lord's answer: Zion mocks the boasting king; God will put a hook in his nose and turn him back; he will not enter the city or shoot an arrow at it, for the Lord defends it for His own sake and David's. That night the angel of the Lord slays 185,000 in the Assyrian camp, and Sennacherib is killed by his own sons in Nineveh.",
    context:"Hezekiah prays in the temple while Isaiah promises deliverance from Sennacherib's threat against Jerusalem.",
    keyVerses:[
      { ref:"2 Kings 19:15", text:"And Hezekiah prayed before the LORD, and said, O LORD God of Israel, which dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth; thou hast made heaven and earth." },
      { ref:"2 Kings 19:19", text:"Now therefore, O LORD our God, I beseech thee, save thou us out of his hand, that all the kingdoms of the earth may know that thou art the LORD God, even thou only." },
      { ref:"2 Kings 19:35", text:"And it came to pass that night, that the angel of the LORD went out, and smote in the camp of the Assyrians an hundred fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses." }
    ],
    takeaway:"Spread your troubles before the Lord in prayer; He hears and defends His people for His name's sake.",
    quiz:[
      { q:"What happened to the Assyrian camp the night after Hezekiah's prayer?", choices:["A storm flooded their trenches","Their allies deserted","An angel of the Lord smote a hundred fourscore and five thousand","Famine broke out in their camp"], a:2, why:"The angel of the LORD went out and smote 185,000 in the Assyrian camp, and those who rose early found them all dead." },
      { q:"Why did Hezekiah spread Sennacherib's letter before the Lord in the temple?", choices:["To file it in the treasury","To show Isaiah he was angry","To copy it for the priests","To turn the threat into prayer, asking God to save them so all kingdoms would know He alone is God"], a:3, why:"Hezekiah prayed that the Lord, who made heaven and earth, would hear Sennacherib's reproach and deliver Jerusalem for His own glory." },
      { q:"What does the Lord's defense of Jerusalem reveal about why He saves His people?", choices:["Jerusalem's walls were the strongest","For His own sake and His servant David's sake, upholding His name and covenant","Judah paid the largest tribute","Assyria feared Egypt"], a:1, why:"The Lord said He would defend the city to save it for His own sake and for David's, not because of Judah's strength." }
    ] },
  { n:20, summary:"Sick unto death, Hezekiah is told by Isaiah to set his house in order, for he shall die and not live. The king turns his face to the wall, prays, and weeps sore — and before Isaiah reaches the middle court, the Lord's word sends him back: I have heard thy prayer, I have seen thy tears; I will heal thee, add fifteen years, and deliver him and the city from Assyria. A lump of figs heals the boil, and as a sign the shadow returns backward ten degrees on the dial of Ahaz. Berodach-baladan of Babylon then sends letters and a present, and Hezekiah shows his envoys every treasure in the house. Isaiah asks what they have seen, then announces the consequence: all shall be carried to Babylon, and Hezekiah's sons will be eunuchs in the Babylonian palace. The king accepts the word as good, for peace and truth will be in his days.",
    context:"The Lord grants sick Hezekiah fifteen years, but his display of treasures to Babylon's envoys draws a prophecy of exile.",
    keyVerses:[
      { ref:"2 Kings 20:5", text:"Turn again, and tell Hezekiah the captain of my people, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will heal thee: on the third day thou shalt go up unto the house of the LORD." },
      { ref:"2 Kings 20:17", text:"Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store unto this day, shall be carried into Babylon: nothing shall be left, saith the LORD." },
      { ref:"2 Kings 20:19", text:"Then said Hezekiah unto Isaiah, Good is the word of the LORD which thou hast spoken. And he said, Is it not good, if peace and truth be in my days?" }
    ],
    takeaway:"The Lord hears prayers and tears, and His word stands whether it brings healing or warning.",
    quiz:[
      { q:"How many years did the Lord add to Hezekiah's life?", choices:["Fifteen","Ten","Thirty","Five"], a:0, why:"The word came back while Isaiah was still in the middle court: I will heal thee, and add unto thy days fifteen years." },
      { q:"What consequence followed Hezekiah showing all his treasures to Babylon's envoys?", choices:["Babylon formed a military alliance with Judah","The envoys brought a second sickness","Isaiah foretold that everything would be carried to Babylon and his sons made eunuchs there","Hezekiah was forgiven without consequence"], a:2, why:"Isaiah announced that the days would come when nothing would be left of the treasured store and Hezekiah's sons would serve in Babylon's palace." },
      { q:"What do Hezekiah's healing and its aftermath teach together?", choices:["Prayer changes nothing","Signs always prevent later mistakes","Wealth impresses nations into friendship","The Lord hears desperate prayer, yet blessings must be handled with humility, not display"], a:3, why:"The Lord heard Hezekiah's weeping prayer and healed him, but the king's display of all his riches drew a prophecy of future exile." }
    ] },
  { n:21, summary:"Manasseh, crowned at twelve, reigns fifty-five years and systematically undoes Hezekiah's reform: he rebuilds the high places, raises altars for Baal, makes a grove like Ahab's, worships all the host of heaven, sets altars for the host of heaven in the two courts of the temple, makes his son pass through the fire, deals with familiar spirits and wizards, and places a graven image in the very house where the Lord promised to put His name forever. He seduces Judah into more evil than the nations the Lord destroyed and fills Jerusalem with innocent blood. Through His prophets the Lord announces judgment beyond hearing: He will stretch over Jerusalem the line of Samaria and wipe the city like a dish, forsaking the remnant to their enemies. Amon follows with two years of the same idolatry, is slain by his servants, and the people make his son Josiah king.",
    context:"Manasseh and Amon lead fifty-seven years of idolatry in Judah, reversing Hezekiah's reform and drawing the prophets' sentence of judgment.",
    keyVerses:[
      { ref:"2 Kings 21:9", text:"But they hearkened not: and Manasseh seduced them to do more evil than did the nations whom the LORD destroyed before the children of Israel." },
      { ref:"2 Kings 21:12", text:"Therefore thus saith the LORD God of Israel, Behold, I am bringing such evil upon Jerusalem and Judah, that whosoever heareth of it, both his ears shall tingle." },
      { ref:"2 Kings 21:13", text:"And I will stretch over Jerusalem the line of Samaria, and the plummet of the house of Ahab: and I will wipe Jerusalem as a man wipeth a dish, wiping it, and turning it upside down." }
    ],
    takeaway:"Wicked leadership can lead a whole people toward judgment; righteousness must be rebuilt deliberately.",
    quiz:[
      { q:"How long did Manasseh reign in Jerusalem?", choices:["Twenty-nine years","Fifty-five years","Twelve years","Forty years"], a:1, why:"Manasseh was twelve years old when he began to reign, and he reigned fifty and five years in Jerusalem." },
      { q:"What made Manasseh's sin especially serious?", choices:["He was untrained in the law","He ruled too briefly to reform","He taxed the temple heavily","He rebuilt idolatry in the temple itself and seduced Judah into worse evil than the destroyed nations"], a:3, why:"He set altars and a graven image in the house where the Lord said He would put His name, made Judah to sin, and filled Jerusalem with innocent blood." },
      { q:"What did the Lord's sentence through the prophets establish?", choices:["Persistent wickedness by a nation's leader draws certain, announced judgment","Temple worship can absorb any sin","Judah was beyond all hope","Prophets speak only for their own generation"], a:0, why:"The Lord declared evil such that ears would tingle, wiping Jerusalem like a dish, because Manasseh provoked Him and made Judah to sin." }
    ] },
  { n:22, summary:"Josiah is eight years old when crowned and does right, walking in all the way of David and turning not aside to the right hand or the left. In his eighteenth year he sends Shaphan the scribe to Hilkiah the high priest to gather the temple money for repairs, given to carpenters, builders, and masons who deal faithfully without reckoning. In the course of the work Hilkiah announces, I have found the book of the law in the house of the Lord, and Shaphan reads it before the king. Hearing the words, Josiah rents his clothes and sends a delegation to inquire of the Lord, for great is the wrath kindled because the fathers hearkened not. Huldah the prophetess confirms that evil is coming on the place, but to the king whose heart was tender and who humbled himself and wept, the Lord grants that he will be gathered to his grave in peace.",
    context:"Young Josiah of Judah funds temple repairs, where Hilkiah the high priest finds the book of the law and Huldah the prophetess answers.",
    keyVerses:[
      { ref:"2 Kings 22:2", text:"And he did that which was right in the sight of the LORD, and walked in all the way of David his father, and turned not aside to the right hand or to the left." },
      { ref:"2 Kings 22:8", text:"And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it." },
      { ref:"2 Kings 22:19", text:"Because thine heart was tender, and thou hast humbled thyself before the LORD, when thou heardest what I spake against this place, and against the inhabitants thereof, that they should become a desolation and a curse, and hast rent thy clothes, and wept before me; I also have heard thee, saith the LORD." }
    ],
    takeaway:"A tender, humble heart before God's word turns even announced judgment toward mercy.",
    quiz:[
      { q:"Who found the book of the law in the temple?", choices:["Shaphan the scribe","Josiah himself","Huldah","Hilkiah the high priest"], a:3, why:"Hilkiah the high priest told Shaphan that he had found the book of the law in the house of the LORD, and gave it to him to read." },
      { q:"Why did Josiah rent his clothes when the book was read?", choices:["He saw the wrath foretold because the fathers had not kept the law","He disagreed with its contents","He was mourning his father","The book condemned Hilkiah"], a:0, why:"Hearing the words, he recognized that great was the wrath of the LORD kindled against them because their fathers hearkened not to the book." },
      { q:"What did Huldah's answer show about how the Lord regards a humble heart?", choices:["He softens His law for kings","He hears those who tender their hearts, humble themselves, and weep before Him","Only priests may inquire of the Lord","Prophecy always means doom"], a:1, why:"Because Josiah's heart was tender and he humbled himself and rent his clothes and wept, the Lord heard him and granted that his eyes would not see the evil." }
    ] },
  { n:23, summary:"The young king gathers all Judah, reads the book of the covenant to them, and stands to a covenant to walk after the Lord with all the heart. The purge follows: vessels made for Baal are burned, idolatrous priests are put down, the grove is burned to powder, the houses of the sodomites are broken, high places are defiled from Geba to Beer-sheba, Topheth is spoiled of child sacrifice, the horses and chariots of the sun are destroyed, and altars from Solomon's days to Manasseh's are beaten down. At Beth-el he burns men's bones on Jeroboam's altar, fulfilling the word of the man of God before, yet spares that prophet's tomb. A Passover such as was not kept from the days of the judges is held, and no king turned to the Lord as Josiah did — yet the wrath kindled by Manasseh is not turned away. Josiah falls at Megiddo before Pharaoh-nechoh; Jehoahaz reigns three months until Egypt sets Jehoiakim on the throne in his place.",
    context:"Josiah renews the covenant, purges Judah's idolatry, and keeps a landmark Passover before falling at Megiddo to Pharaoh-nechoh of Egypt.",
    keyVerses:[
      { ref:"2 Kings 23:3", text:"And the king stood by a pillar, and made a covenant before the LORD, to walk after the LORD, and to keep his commandments and his testimonies and his statutes with all their heart and all their soul, to perform the words of this covenant that were written in this book. And all the people stood to the covenant." },
      { ref:"2 Kings 23:25", text:"And like unto him was there no king before him, that turned to the LORD with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him." },
      { ref:"2 Kings 23:26", text:"Notwithstanding the LORD turned not from the fierceness of his great wrath, wherewith his anger was kindled against Judah, because of all the provocations that Manasseh had provoked him withal." }
    ],
    takeaway:"Wholehearted return to the Lord is always worth making, even when old consequences remain.",
    quiz:[
      { q:"Who killed Josiah at Megiddo?", choices:["Nebuchadnezzar of Babylon","Pekah of Israel","Pharaoh-nechoh of Egypt","Tiglath-pileser of Assyria"], a:2, why:"Pharaoh-nechoh went up against the king of Assyria by the river Euphrates, and Josiah went against him and was slain at Megiddo." },
      { q:"Why did Josiah burn bones on the altar at Beth-el?", choices:["To punish Beth-el's living citizens","To fulfill the word the man of God had proclaimed against that altar long before","To hide evidence of idolatry","An Egyptian general commanded it"], a:1, why:"He destroyed Jeroboam's altar and burned men's bones upon it, according to the word of the LORD the man of God proclaimed, sparing that prophet's own tomb." },
      { q:"What does the statement that judgment still stood after Josiah's reform teach?", choices:["Reforms are useless","God forgets His warnings","Josiah's Passover was invalid","National turning matters, yet long-accumulated, unrepented evil still brings its harvest"], a:3, why:"Notwithstanding the reform, the LORD turned not from His wrath kindled by Manasseh's provocations, showing that wholehearted reform does not cancel every consequence." }
    ] },
  { n:24, summary:"Nebuchadnezzar of Babylon comes up, and Jehoiakim serves him three years before rebelling. Bands of Chaldees, Syrians, Moabites, and children of Ammon are sent against Judah — at the commandment of the Lord, to remove the nation out of His sight for Manasseh's sins and the innocent blood he shed, which the Lord would not pardon. Jehoiakim dies, and his son Jehoiachin reigns three evil months before Babylon's servants besiege Jerusalem. He surrenders in Nebuchadnezzar's eighth year; the treasures of temple and palace are carried off, Solomon's gold vessels are cut in pieces, and ten thousand captives — seven thousand men of might and a thousand craftsmen and smiths — go to Babylon, leaving only the poorest of the people. Nebuchadnezzar installs Mattaniah as Zedekiah, who in time rebels against Babylon, through the anger of the Lord, until Jerusalem and Judah are cast out of His presence.",
    context:"Babylon under Nebuchadnezzar replaces Egypt as Judah's master; the first deportations carry king and craftsmen to Babylon.",
    keyVerses:[
      { ref:"2 Kings 24:3", text:"Surely at the commandment of the LORD came this upon Judah, to remove them out of his sight, for the sins of Manasseh, according to all that he did;" },
      { ref:"2 Kings 24:13", text:"And he carried out thence all the treasures of the house of the LORD, and the treasures of the king's house, and cut in pieces all the vessels of gold which Solomon king of Israel had made in the temple of the LORD, as the LORD had said." },
      { ref:"2 Kings 24:20", text:"For through the anger of the LORD it came to pass in Jerusalem and Judah, until he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon." }
    ],
    takeaway:"The Lord's warnings through prophets are sure; neither throne nor temple shields impenitent people.",
    quiz:[
      { q:"How many captives were carried from Jerusalem in Jehoiachin's time?", choices:["Ten thousand","Three hundred","Seventy","One thousand"], a:0, why:"Nebuchadnezzar carried away all Jerusalem's princes and mighty men, even ten thousand captives, including seven thousand men of might and a thousand craftsmen and smiths." },
      { q:"Why did these calamities come upon Judah, in the historian's words?", choices:["Jehoiachin's youth","Egypt's invasion","A series of accidents and weak alliances","At the commandment of the LORD, for Manasseh's sins and the innocent blood he shed"], a:3, why:"The chapter states the LORD sent the spoiler bands and that Judah was removed from His sight for the sins of Manasseh, which He would not pardon." },
      { q:"What does Zedekiah's final rebellion show about the people's condition?", choices:["Babylon was easy to defeat","Zedekiah acted on the Lord's command","Through the anger of the LORD, Judah persisted in rebellion until cast out of His presence","Egypt forced the rebellion"], a:2, why:"The chapter says that through the anger of the LORD it came to pass that Zedekiah rebelled against the king of Babylon, sealing Judah's removal." }
    ] },
  { n:25, summary:"In Zedekiah's ninth year Nebuchadnezzar besieges Jerusalem, and by the eleventh year famine prevails and the city is broken up. Zedekiah's night flight is overtaken in the plains of Jericho; his sons are slain before his eyes, his eyes are put out, and he is carried in brass fetters to Babylon. Nebuzar-adan, captain of the guard, burns the house of the Lord, the king's house, and every great house, breaks down Jerusalem's walls, and carries the people to Babylon, leaving only the poor of the land as vinedressers. The pillars, brasen sea, and vessels of Solomon's temple go to Babylon as plunder, and priests and officers are slain at Riblah — so Judah is carried away out of their land. Gedaliah governs the remnant until Ishmael of the seed royal murders him, and the frightened people flee to Egypt. Thirty-seven years into captivity, Evil-merodach speaks kindly to Jehoiachin, changes his prison garments, and gives him a continual allowance all his days.",
    context:"Nebuchadnezzar's siege ends in Jerusalem's fall: temple burned, Judah exiled, Gedaliah governor and slain, and captive Jehoiachin favored at last.",
    keyVerses:[
      { ref:"2 Kings 25:9", text:"And he burnt the house of the LORD, and the king's house, and all the houses of Jerusalem, and every great man's house burnt he with fire." },
      { ref:"2 Kings 25:21", text:"And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land." },
      { ref:"2 Kings 25:28", text:"And he spake kindly to him, and set his throne above the throne of the kings that were with him in Babylon;" }
    ],
    takeaway:"Judgment falls exactly as spoken, yet the Lord preserves a remnant and a future for the faithful.",
    quiz:[
      { q:"What did the Chaldees do to Zedekiah when they captured him?", choices:["They crowned him in Babylon","They slew his sons before his eyes and put out his eyes","They released him at Riblah","They made him a vinedresser"], a:1, why:"They slew the sons of Zedekiah before his eyes, put out his eyes, bound him with fetters of brass, and carried him to Babylon." },
      { q:"Why does the book end with the account of Jehoiachin's release from prison?", choices:["To prove Babylon was merciful to all","To list the temple vessels taken","A small light of hope: the Lord did not forget David's line even in exile","To show Judah soon returned home"], a:2, why:"In the seven and thirtieth year of his captivity, Evil-merodach spake kindly to Jehoiachin, set his throne above other kings, and gave him a continual allowance all his days." },
      { q:"What does the fall of Jerusalem confirm about the Lord's word spoken by the prophets?", choices:["Every warning was fulfilled exactly, from exile to the temple's burning","Prophecies of judgment are usually exaggerated","The temple could never be destroyed","Exile ended the covenant"], a:0, why:"The burning of the house, the king's blindness, the deportation, and the carrying away of the vessels came just as the Lord had said through His servants." }
    ] }
);
